import React, {useState} from 'react'
import { useDataLayerValue } from '../DataLayer'
import Contact from './Contact';
import About from './About';
import content from '../content';



function Profile() {

    const [{page},dispatch] = useDataLayerValue();
    const [about,setAbout] = useState(false)
    const [contact,setContact] = useState(false)
    const [box, setBox] = useState(['1','2','3','3','3','2','1'])

    const toggleAbout =  () => {
        setAbout(true);
        setContact(false);
    }

    const toggleContact =  () => {
        setContact(true);
        setAbout(false);
    }

    const mainPage = () => {
        dispatch({
          type: "SET_PAGE",
          page: "main",
        });
      }


    return (
        <div>
            <img className={"absolute mx-4 my-2 w-8 opacity-40 hover:opacity-100"} onClick={mainPage} src={content.back}></img>
            <div className={"w-screen h-screen flex flex-wrap place-content-center"}>
                {box.map((items, index) => {return (
                            <div  className={"w-12 h-12 bg-yellow-"+{items}+"00"}>
                                {items}
                            </div>
                          );
                      })}


                <div className={`${contact ? "" : "hidden"} mt-10`}>
                    <Contact/>
                </div>
                <div className={`${about ? "" : "hidden"} mt-10`}>
                    <About/>
                </div>


            </div>

        </div>
    )
}

export default Profile
